      { sku: 'DEV-HOUR', qty: 3, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 },
    ],
  };
  assert.deepEqual(removeLine(nonDraftInvoice, 'DES-HOUR'), { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate the original invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  const invoiceCopy = JSON.stringify(invoice);
  removeLine(invoice, 'DES-HOUR');
  assert.equal(JSON.stringify(invoice), invoiceCopy);
});

test('addLine and removeLine can chain on a draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const r2 = addLine(r.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  const r3 = addLine(r2.value, { sku: 'COPY-HOUR', qty: 2 });
  assert.equal(r3.ok, true);
  assert.equal(r3.value.lines.length, 3);
  const r4 = removeLine(r3.value, 'DEV-HOUR');
  assert.equal(r4.ok, true);
  assert.equal(r4.value.lines.length, 2);
  assert.deepEqual(r4.value.lines.map(l => l.sku), ['DES-HOUR', 'COPY-HOUR']);
});

test('issueInvoice assigns a number and changes status to issued', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const invoice = r.value;
  const r2 = issueInvoice(invoice, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2026-0001');
  assert.equal(r2.value.status, 'issued');
  assert.equal(r2.value.customerId, 'C-001');
  assert.equal(r2.value.issueDate, '2026-10-07');
});

test('issueInvoice uses existing numbers to avoid conflicts', () => {
